// The file is embedded gzip+base64 so the module stays a single self-contained
// file: Node and the browser both decode it with the same standard primitives.
import { gunzipSync } from 'node:zlib';

const PAYLOAD = '';

function decode() {
  const binary = Buffer.from(PAYLOAD, 'base64');
  return gunzipSync(binary).toString('utf8');
}

let cached = null;

/** Evaluate the vendored CommonJS module and return its exports. */
export function marchingCubesModule() {
  if (cached) return cached;
  const source = decode();
  const module = { exports: {} };
  // eslint-disable-next-line no-new-func
  const factory = new Function('module', 'exports', source);
  factory(module, module.exports);
  cached = module.exports;
  return cached;
}

export function marchingCubes(dims, potential, bounds) {
  return marchingCubesModule().marchingCubes(dims, potential, bounds);
}

export function surfaceNets(dims, potential, bounds) {
  return marchingCubesModule().surfaceNets(dims, potential, bounds);
}

export function marchingTetrahedra(dims, potential, bounds) {
  return marchingCubesModule().marchingTetrahedra(dims, potential, bounds);
}

export default marchingCubesModule;
